        while q:
            r,c=q.popleft()
            for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                rr,cc=r+dr,c+dc
                if 0<=rr<h and 0<=cc<w and arr[rr,cc]==target and d[rr,cc]>d[r,c]+1:
